export { descriptionId, view } from "../../../foldkit/ui/select";
export type { SelectAttributes, ViewConfig } from "../../../foldkit/ui/select";

export {
  baseUiSelectChevronClasses,
  baseUiSelectControlClasses,
  baseUiSelectDescriptionClasses,
  baseUiSelectLabelClasses,
  baseUiSelectWrapperClasses,
} from "./view";

export {
  chevronClasses as baseUiSelectChevronClasses,
  descriptionClasses as baseUiSelectDescriptionClasses,
  labelClasses as baseUiSelectLabelClasses,
  selectClasses as baseUiSelectControlClasses,
  selectWrapperClasses as baseUiSelectWrapperClasses,
} from "../../../foldkit/ui/select/view";

import { describe, expect, test } from "vitest";

import * as Select from "./index";

describe("Base UI Select registry view", () => {
  test("reuses the Foldkit Select functional contract", () => {
    expect(Select.view).toBeTypeOf("function");
    expect(Select.descriptionId).toBeTypeOf("function");
    expect(Select.baseUiSelectControlClasses).toContain("rounded");
  });
});
